      _autoFoldCount = 0;
      turnSub();
      await releasePowerAssertions();
      await _cubeCacheSaveQuietly();
      await interruptSub.cancel();
      await taskSub.cancel();
      hepSub?.call();
      streamJsonSub?.call();
