  /// idle → a fresh run (the parent wakes). Text-only — the digest never
  /// spawns or cancels anything.
  void _deliverHeartbeatDigest(String digest) {
    if (_exited) return;
    if (isBusy) {
      _agent.steer(UserMessage.text(digest));
    } else {
      _startRun(digest);
