) {
  if (turnUpdate == null) return (currentContext, currentConfig);
  if (turnUpdate.context != null) currentContext = turnUpdate.context!;
  if (turnUpdate.model != null) {
    currentConfig = currentConfig.copyWith(model: turnUpdate.model);
